import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    # Remove path separators but preserve the rest
    return filename.replace('/', '').replace('\\', '')

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    original_name = sanitize_filename(uploaded.filename)

    # Save to temp location
    tmp = tempfile.NamedTemporaryFile(delete=False, dir=UPLOAD_DIR, suffix='_' + original_name)
    uploaded.save(tmp.name)
    tmp.close()

    output_format = request.form.get('format', 'pdf')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {tmp.name}'

    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30, text=True)
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr}), 500

        output_path = tmp.name.rsplit('.', 1)[0] + '.' + output_format.split(' ')[0]
        if os.path.exists(output_path):
            with open(output_path, 'rb') as f:
                content = f.read()
            os.unlink(output_path)
            os.unlink(tmp.name)
            return content, 200, {'Content-Type': 'application/octet-stream'}
        else:
            os.unlink(tmp.name)
            return jsonify({'error': 'Output file not found'}), 500
    except subprocess.TimeoutExpired:
        os.unlink(tmp.name)
        return jsonify({'error': 'Conversion timed out'}), 504

@app.route('/thumbnail', methods=['POST'])
def generate_thumbnail():
    """Generate thumbnail for uploaded image"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not allowed_file(uploaded.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    width = request.form.get('width', '200')
    height = request.form.get('height', '200')

    tmp = tempfile.NamedTemporaryFile(delete=False, dir=UPLOAD_DIR, suffix='.png')
    uploaded.save(tmp.name)
    tmp.close()

    output_path = tmp.name + '_thumb.png'

    # ImageMagick resize
    cmd = f'convert {tmp.name} -resize {width}x{height} {output_path}'

    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=15, text=True)
        if result.returncode != 0:
            return jsonify({'error': 'Thumbnail generation failed'}), 500

        with open(output_path, 'rb') as f:
            content = f.read()
        os.unlink(output_path)
        os.unlink(tmp.name)
        return content, 200, {'Content-Type': 'image/png'}
    except subprocess.TimeoutExpired:
        os.unlink(tmp.name)
        return jsonify({'error': 'Timeout'}), 504

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
